type PanelCopy=typeof panelCopy.en;
const panelLocaleOf=(staff:any,from?:TgFrom):BotLocale=>{const v=String(staff?.u?.management_language||'').toLowerCase();return v==='uk'||v==='pl'||v==='en'?v as BotLocale:localeOf(from)};
const pcopy=(locale:BotLocale):PanelCopy=>panelCopy[locale] as unknown as PanelCopy;
const languageName=(locale:BotLocale)=>locale==='uk'?'Українська':locale==='pl'?'Polski':'English';
const startCommandLabel=(locale:BotLocale)=>l3(locale,'Відкрити меню','Otwórz menu','Open menu');
async function syncStartCommand(env:Env,telegramUserId:number,locale:BotLocale){
 if(!env.BOT_TOKEN||!telegramUserId)return;
 await tgApi(env,'setMyCommands',{commands:[{command:'start',description:startCommandLabel(locale)}],scope:{type:'chat',chat_id:telegramUserId}}).catch(e=>console.error('setMyCommands /start failed',telegramUserId,e));
}
const persistentMenuLabel=(locale:BotLocale)=>l3(locale,'🦎 Відкрити меню','🦎 Otwórz menu','🦎 Open menu');
const persistentMenuKeyboard=(locale:BotLocale)=>({keyboard:[[{text:persistentMenuLabel(locale)}]],resize_keyboard:true,is_persistent:true,input_field_placeholder:startCommandLabel(locale)});
async function showPersistentMenuKeyboard(env:Env,chatId:number,locale:BotLocale){
 if(!env.BOT_TOKEN||!chatId)return;
 try{
  const sent:any=await sendMessage(env,chatId,'\u2063',persistentMenuKeyboard(locale));
  if(sent?.message_id)await deleteMessageSafe(env,chatId,Number(sent.message_id));
 }catch(e){console.error('persistent menu keyboard failed',chatId,e)}
}
const messageControlKeyboard=(locale:BotLocale,pinned=false)=>({inline_keyboard:[[
 {text:pinned?l3(locale,'📍 Відкріпити','📍 Odepnij','📍 Unpin'):l3(locale,'📌 Закріпити','📌 Przypnij','📌 Pin'),callback_data:`msgctl:${pinned?'unpin':'pin'}:${locale}`},
 {text:l3(locale,'✅ Прочитано','✅ Przeczytano','✅ Read'),callback_data:`msgctl:read:${locale}`}
]]});
const messageControlMarkup=(msg:any,locale:BotLocale,pinned:boolean)=>{
 const rows=Array.isArray(msg?.reply_markup?.inline_keyboard)?msg.reply_markup.inline_keyboard:[];
 const keep=rows.filter((row:any[])=>!row.some((b:any)=>String(b?.callback_data||'').startsWith('msgctl:')));
 return {inline_keyboard:[...keep,...messageControlKeyboard(locale,pinned).inline_keyboard]};
};

export const telegramWebhookSecret=(env:Env)=>{const v=String(env.TELEGRAM_WEBHOOK_SECRET||'').trim();return /^[A-Za-z0-9_-]{1,256}$/.test(v)?v:''};
function appUrl(env:Env,origin?:string){const live=(origin||'').trim();if(/^https:\/\//i.test(live))return live.replace(/\/$/,'');return String(env.APP_URL||'').replace(/\/$/,'')}
function mainKeyboard(env:Env,origin:string,locale:BotLocale,role:Role='CLIENT'){const c=copy[locale],url=appUrl(env,origin);const rows:any[]=[[{text:c.open,web_app:{url}}]];if(role!=='CLIENT')rows.push([{text:role==='OWNER'?c.panel:l3(locale,'🛠 Панель керування','🛠 Panel zarządzania','🛠 Management panel'),callback_data:'staff:panel'}]);rows.push([{text:c.settings,callback_data:'client:settings'}]);return {inline_keyboard:rows}}
async function clientSettingsKeyboard(env:Env,userId:number,locale:BotLocale){let enabled=true;if(env.DB&&userId){await ensureDb(env);const r=await env.DB.prepare('SELECT notifications_enabled FROM users WHERE id=?').bind(userId).first<any>();enabled=Number(r?.notifications_enabled??1)===1}return {inline_keyboard:[[{text:enabled?l3(locale,'🔔 Оповіщення: УВІМК.','🔔 Powiadomienia: WŁ.','🔔 Notifications: ON'):l3(locale,'🔕 Оповіщення: ВИМК.','🔕 Powiadomienia: WYŁ.','🔕 Notifications: OFF'),callback_data:'client:notifications:toggle'}],[{text:l3(locale,'🌐 Мова','🌐 Język','🌐 Language'),callback_data:'botlang:menu'},{text:copy[locale].help,callback_data:'help'}],[{text:l3(locale,'📱 Поділитися номером','📱 Udostępnij numer','📱 Share phone number'),callback_data:'client:phone'}],[{text:l3(locale,'⬅️ Головне меню','⬅️ Menu główne','⬅️ Main menu'),callback_data:'client:menu'}]]}}
async function clientSettingsText(env:Env,locale:BotLocale){return botContent(env,'bot.client_settings_text',locale,l3(locale,`⚙️ <b>Налаштування</b>

Керуйте оповіщеннями про статус ваших заявок, мовою бота та швидким доступом до допомоги.`,`⚙️ <b>Ustawienia</b>

Zarządzaj powiadomieniami o statusie zleceń, językiem bota i szybkim dostępem do pomocy.`,`⚙️ <b>Settings</b>

Manage request-status notifications, bot language and quick access to help.`))}
async function botContent(env:Env,key:string,locale:BotLocale,fallback:string){if(!env.DB)return fallback;await ensureDb(env);const row=await env.DB.prepare('SELECT value FROM content_blocks WHERE key=? AND locale=?').bind(key,locale).first<any>();const value=String(row?.value||'').trim();return value||fallback}
const botLocaleFromUser=(u:any,from?:TgFrom):BotLocale=>{const v=String(u?.language||'').toLowerCase();return v==='uk'||v==='pl'||v==='en'?v as BotLocale:localeOf(from)};
async function helpKeyboard(env:Env,locale:BotLocale){const contact=String(await getSetting(env,'bot.owner_contact_url','')).trim()||`tg://user?id=${String(env.OWNER_TELEGRAM_ID||LOCKED_OWNER_ID)}`;return {inline_keyboard:[[{text:l3(locale,'✍️ Написати власнику Детейлінгу','✍️ Napisz do właściciela','✍️ Message the detailing owner'),url:contact}],[{text:l3(locale,'📱 Добровільно поділитися номером','📱 Dobrowolnie udostępnij numer','📱 Voluntarily share phone number'),callback_data:'client:phone'}],[{text:l3(locale,'🌐 Змінити мову','🌐 Zmień język','🌐 Change language'),callback_data:'botlang:menu'}],[{text:l3(locale,'⬅️ Головне меню','⬅️ Menu główne','⬅️ Main menu'),callback_data:'client:menu'}]]}}


