 await safeEdit(env,msg,l3(locale,'📐 <b>Ширина кнопки</b>\n\nTelegram не дозволяє задавати висоту або піксельну ширину кнопки, тому тут керується її місце в рядку: Wide — одна кнопка в рядку, Half — дві, Compact — до трьох.','📐 <b>Szerokość przycisku</b>\n\nTelegram nie pozwala ustawić wysokości ani pikselowej szerokości, więc sterujemy miejscem w wierszu: Wide — jeden przycisk, Half — dwa, Compact — do trzech.','📐 <b>Button width</b>\n\nTelegram does not expose pixel height/width controls, so this controls row span: Wide — one button per row, Half — two, Compact — up to three.'),{inline_keyboard:[[{text:`${cur==='WIDE'?'✅ ':''}WIDE`,callback_data:`menuedit:setsize:${id}:WIDE`}],[{text:`${cur==='HALF'?'✅ ':''}HALF`,callback_data:`menuedit:setsize:${id}:HALF`},{text:`${cur==='COMPACT'?'✅ ':''}COMPACT`,callback_data:`menuedit:setsize:${id}:COMPACT`}],[{text:l3(locale,'⬅️ Назад','⬅️ Wstecz','⬅️ Back'),callback_data:`menuedit:item:${id}`}],[{text:l3(locale,'✅ Завершити редагування','✅ Zakończ edycję','✅ Finish editing'),callback_data:'menuedit:exit'}]]});
