 const tr=await env.DB.prepare('SELECT locale,title,description FROM service_translations WHERE service_id=? ORDER BY locale').bind(id).all<any>();const translations=(tr.results||[]).map((x:any)=>`${x.locale.toUpperCase()}: <b>${esc(x.title)}</b>\n${esc(x.description)}`).join('\n\n');
 const status=s.archived?'ARCHIVED':s.enabled?'ENABLED':'HIDDEN';
