async function projectDataCounts(env:Env){
 if(!env.DB)return {requests:0,calculations:0,payments:0,analytics:0,clients:0,referrals:0,offers:0,campaigns:0};
 const first=async(sql:string)=>Number((await env.DB!.prepare(sql).first<any>().catch(()=>null))?.n||0);
 return {
  requests:await first('SELECT COUNT(*) n FROM service_requests'),calculations:await first('SELECT COUNT(*) n FROM calculator_sessions'),payments:await first('SELECT COUNT(*) n FROM payments'),analytics:await first('SELECT COUNT(*) n FROM analytics_events'),clients:await first("SELECT COUNT(*) n FROM users WHERE role='CLIENT'"),referrals:await first('SELECT COUNT(*) n FROM referrals'),offers:await first('SELECT COUNT(*) n FROM personal_offers'),campaigns:await first('SELECT COUNT(*) n FROM broadcast_campaigns')
 };
}
async function resetCollectedProjectData(env:Env,actorUserId:number){
 if(!env.DB)throw new Error('D1 unavailable');await ensureDb(env);
 const before=await projectDataCounts(env);
 const sql=[
  'DELETE FROM service_request_extras','DELETE FROM delivery_requests','DELETE FROM payments','DELETE FROM service_requests',
  'DELETE FROM calculator_session_options','DELETE FROM calculator_sessions','DELETE FROM personal_offer_services','DELETE FROM personal_offers',
  'DELETE FROM personal_discounts','DELETE FROM referrals','DELETE FROM campaign_deliveries','DELETE FROM broadcast_campaigns',
  'DELETE FROM analytics_events','DELETE FROM vip_history','DELETE FROM whitelist','DELETE FROM blacklist','DELETE FROM client_profiles',
  'DELETE FROM bot_state',"DELETE FROM users WHERE role='CLIENT'",'DELETE FROM audit_log'
 ];
 for(const q of sql)await env.DB.prepare(q).run().catch(()=>{});
 await env.DB.prepare("DELETE FROM sqlite_sequence WHERE name IN ('service_requests','service_request_extras','delivery_requests','payments','calculator_sessions','vip_history','whitelist','blacklist','referrals','analytics_events','broadcast_campaigns','campaign_deliveries','personal_discounts','personal_offers','personal_offer_services')").run().catch(()=>{});
 await env.DB.prepare('INSERT OR IGNORE INTO client_profiles(user_id) SELECT id FROM users WHERE role IN (\'OWNER\',\'ADMIN\',\'MANAGER\')').run().catch(()=>{});
 await env.DB.prepare('INSERT INTO audit_log(actor_user_id,action,entity_type,entity_id,old_data_json,new_data_json) VALUES(?,?,?,?,?,?)').bind(actorUserId,'project.data.reset','system','project',JSON.stringify(before),JSON.stringify({preserved:'settings, services, pricing, themes, schedules, menu layout, staff roles'})).run();
 return before;
}

function paymentMethodLabel(locale:BotLocale,method:string){
 const m=String(method||'').toUpperCase();
 if(m==='CASH')return l3(locale,'💵 Готівка','💵 Gotówka','💵 Cash');
 if(m==='CARD')return l3(locale,'💳 Картка','💳 Karta','💳 Card');
 return method||'—';
}
async function orderPaymentDetail(env:Env,msg:TgMessage,from:TgFrom,id:number){
 const staff=await requireStaff(env,from,'orders.read');if(!staff||!env.DB)return;await ensureDb(env);const locale=panelLocaleOf(staff,from);
 const r=await env.DB.prepare("SELECT id,user_id,status,calculated_price,final_job_price,currency,payment_status,staff_deleted_at FROM service_requests WHERE id=? AND staff_deleted_at IS NULL").bind(id).first<any>();
 if(!r){await safeEdit(env,msg,l3(locale,'⚠️ Заявку не знайдено.','⚠️ Nie znaleziono zlecenia.','⚠️ Request not found.'),{inline_keyboard:msg.chat.type==='private'?[[{text:l3(locale,'⬅️ До заявок','⬅️ Do zleceń','⬅️ Back to requests'),callback_data:'panel:requests'}]]:[]});return}
 const p=await env.DB.prepare("SELECT id,amount,currency,method,status,paid_at,marked_by FROM payments WHERE service_request_id=? AND status='PAID' ORDER BY id DESC LIMIT 1").bind(id).first<any>();
 const amount=Number((p?.amount??r.final_job_price??r.calculated_price)??0).toFixed(2);
 const currency=String(p?.currency||r.currency||'PLN');
 const status=p?'PAID':String(r.payment_status||'PENDING');
 const method=p?paymentMethodLabel(locale,String(p.method||'')):'—';
 const paidAt=p?.paid_at?fmtDate(p.paid_at):'—';
 const text='💳 <b>Payments · #'+id+'</b>\n\n'+l3(locale,'Статус','Status','Status')+': <b>'+esc(status)+'</b>\n'+l3(locale,'Сума','Kwota','Amount')+': <b>'+amount+' '+esc(currency)+'</b>\n'+l3(locale,'Спосіб','Metoda','Method')+': <b>'+esc(method)+'</b>'+(p?'\n'+l3(locale,'Оплачено','Opłacono','Paid at')+': <b>'+esc(paidAt)+'</b>':'');
 const rows:any[]=[];
 if(!p&&await canStaff(env,staff.role,'orders.manage'))rows.push([{text:l3(locale,'✅ Оплачено','✅ Opłacono','✅ Mark paid'),callback_data:'order:'+id+':paid'}]);
 rows.push([{text:l3(locale,'⬅️ До заявки','⬅️ Do zlecenia','⬅️ Back to request'),callback_data:'order:'+id+':open'}]);
 await safeEdit(env,msg,text,{inline_keyboard:rows});
}
async function orderPaymentMethodPicker(env:Env,msg:TgMessage,from:TgFrom,id:number){
 const staff=await requireStaff(env,from,'orders.manage');if(!staff||!env.DB)return;await ensureDb(env);const locale=panelLocaleOf(staff,from);
 const p=await env.DB.prepare("SELECT id FROM payments WHERE service_request_id=? AND status='PAID' ORDER BY id DESC LIMIT 1").bind(id).first<any>();
 if(p){await orderPaymentDetail(env,msg,from,id);return}
 const r=await env.DB.prepare("SELECT id,calculated_price,final_job_price,currency FROM service_requests WHERE id=? AND staff_deleted_at IS NULL").bind(id).first<any>();
 if(!r){await orderPaymentDetail(env,msg,from,id);return}
 const amount=Number((r.final_job_price??r.calculated_price)??0).toFixed(2);
 await safeEdit(env,msg,'✅ <b>'+l3(locale,'Позначити як оплачено','Oznacz jako opłacone','Mark as paid')+'</b>\n\n'+l3(locale,'Сума','Kwota','Amount')+': <b>'+amount+' '+esc(r.currency||'PLN')+'</b>\n\n'+l3(locale,'Оберіть спосіб оплати:','Wybierz metodę płatności:','Choose payment method:'),{inline_keyboard:[[{text:l3(locale,'💵 Готівка','💵 Gotówka','💵 Cash'),callback_data:'order:'+id+':paycash'},{text:l3(locale,'💳 Картка','💳 Karta','💳 Card'),callback_data:'order:'+id+':paycard'}],[{text:pcopy(locale).cancel,callback_data:'order:'+id+':payment'}]]});
}
async function markOrderPaid(env:Env,msg:TgMessage,from:TgFrom,id:number,method:'CASH'|'CARD'){
 const staff=await requireStaff(env,from,'orders.manage');if(!staff||!env.DB)return;await ensureDb(env);
 const r=await env.DB.prepare("SELECT id,user_id,status,payment_status,calculated_price,final_job_price,currency FROM service_requests WHERE id=? AND staff_deleted_at IS NULL").bind(id).first<any>();
 if(!r){await orderPaymentDetail(env,msg,from,id);return}
 const existing=await env.DB.prepare("SELECT id,amount,currency,method,status,paid_at FROM payments WHERE service_request_id=? AND status='PAID' ORDER BY id DESC LIMIT 1").bind(id).first<any>();
 if(!existing){
  const metadata=JSON.stringify({source:'telegram_staff',requestStatus:r.status||null});
  const result:any=await env.DB.prepare("INSERT INTO payments(service_request_id,user_id,amount,currency,method,provider,status,paid_at,marked_by,metadata_json) SELECT sr.id,sr.user_id,COALESCE(sr.final_job_price,sr.calculated_price),sr.currency,?,'MANUAL','PAID',CURRENT_TIMESTAMP,?,? FROM service_requests sr WHERE sr.id=? AND sr.staff_deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM payments p WHERE p.service_request_id=sr.id AND p.status='PAID')").bind(method,staff.u.id,metadata,id).run();
  await env.DB.prepare("UPDATE service_requests SET payment_status='PAID',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id).run();
  if(Number(result?.meta?.changes||0)>0){
   await audit(env,staff.u.id,'order.payment.mark_paid','service_request',String(id),{payment_status:r.payment_status},{payment_status:'PAID',method,amount:Number((r.final_job_price??r.calculated_price)??0),currency:r.currency});
   await event(env,r.user_id,'payment_paid',{requestId:id,method,amount:Number((r.final_job_price??r.calculated_price)??0),currency:r.currency});
  }
 }else if(String(r.payment_status||'')!=='PAID'){
  await env.DB.prepare("UPDATE service_requests SET payment_status='PAID',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id).run();
 }
 await orderPaymentDetail(env,msg,from,id);
}

